            Q('p2', L('Dove scegli per quanto tempo tenere le chat?', 'Where do you choose how long to keep chats?'), [L('Nell’impostazione dell’attività (Keep Activity)', 'In the activity setting (Keep Activity)'), L('Nel calendario', 'In the calendar'), L('Nelle impostazioni del Wi-Fi', 'In Wi-Fi settings'), L('Non si può', 'You cannot')], 0, L('E puoi cancellarle.', 'And you can delete them.')),
            Q('p3', L('Che cosa fare con le app collegate?', 'What should you do with connected apps?'), [L('Autorizzare solo il necessario e rivederle', 'Allow only what is needed and review them'), L('Collegare tutto sempre', 'Always connect everything'), L('Ignorarle', 'Ignore them'), L('Condividere la password', 'Share the password')], 0, L('Minimo privilegio.', 'Least privilege.')),
        ], task('text', L('Scrivi tre regole per usare Gemini con l’account Google personale, una per riga che inizia con `-`, tra cui una sulle **app collegate** e una sui **dati riservati**.', 'Write three rules for using Gemini with your personal Google account, one per line starting with `-`, including one on **connected apps** and one on **confidential data**.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre regole', 'Three rules')), re('collegat|connected|app', L('Una regola sulle app collegate', 'A rule on connected apps')), re('riservat|confidential|sensibil|sensitive|privat', L('Una regola sui dati riservati', 'A rule on confidential data'))], '', "- collegare solo le app che servono e rivederle ogni mese\n- non scrivere dati riservati o di altre persone\n- impostare la cancellazione automatica dell’attività"), [
