        ]),
        lesson('gems', L('Gem e Gemini nel lavoro', 'Gems and Gemini at work'), [
            P('Un **Gem** è una versione di Gemini con istruzioni tue salvate: un correttore di bozze, un tutor di matematica, un assistente per le email. Lo crei una volta e lo riusi, senza ripetere ogni volta il contesto.', 'A **Gem** is a version of Gemini with your own saved instructions: a proofreader, a maths tutor, an email assistant. You create it once and reuse it, without repeating the context every time.'),
            P('Negli account Google Workspace Gemini lavora dentro **Gmail, Documenti, Fogli e Drive**: riassume una conversazione di email, propone una bozza, organizza dati in una tabella. Le regole su quali dati può leggere le decide l’amministratore dell’organizzazione.', 'In Google Workspace accounts Gemini works inside **Gmail, Docs, Sheets and Drive**: it summarises an email thread, drafts a reply, organises data in a table. The rules on which data it can read are set by the organisation’s administrator.'),
            Tip('Dai a ogni Gem un compito preciso: un Gem che fa tutto non fa niente bene.', 'Give each Gem one precise job: a Gem that does everything does nothing well.'),
        ], [
            Q('ge1', L('Che cos’è un Gem?', 'What is a Gem?'), [L('Gemini con istruzioni salvate per un compito', 'Gemini with saved instructions for a task'), L('Un modello più grande', 'A larger model'), L('Un abbonamento', 'A subscription'), L('Un’estensione di Chrome', 'A Chrome extension')], 0, L('Lo crei una volta e lo riusi.', 'Create once, reuse.')),
            Q('ge2', L('Dove lavora Gemini in Workspace?', 'Where does Gemini work in Workspace?'), [L('Dentro Gmail, Documenti, Fogli e Drive', 'Inside Gmail, Docs, Sheets and Drive'), L('Solo nel browser Chrome', 'Only in the Chrome browser'), L('Solo su Android', 'Only on Android'), L('Solo in YouTube', 'Only on YouTube')], 0, L('Accanto ai tuoi file.', 'Next to your files.')),
            Q('ge3', L('Chi decide cosa può leggere Gemini in un’azienda?', 'Who decides what Gemini can read in a company?'), [L('L’amministratore di Workspace', 'The Workspace administrator'), L('Ogni collega a caso', 'Any colleague at random'), L('Nessuno', 'Nobody'), L('Il modello', 'The model')], 0, L('Le regole sono dell’organizzazione.', 'The rules belong to the organisation.')),
        ], task('text', L('Scrivi le istruzioni di un Gem: una riga che inizia con `Sei` (il ruolo) e una che inizia con `Non` (un limite).', 'Write a Gem’s instructions: one line starting with `Sei` (the role) and one starting with `Non` (a limit).'), '', [re('^Sei\s+\S.{5,}', L('Dai un ruolo', 'You give a role')), re('^Non\s+\S.{5,}', L('Metti un limite', 'You set a limit'))], '', "Sei un correttore di bozze per testi scolastici.\nNon riscrivere il contenuto: segnala solo errori e proponi correzioni."), [
            dMatch(pMatch(), [['Gem', L('Istruzioni salvate', 'Saved instructions')], ['Gmail', L('Riassunti di email', 'Email summaries')], ['Fogli', L('Dati in tabella', 'Data in tables')], ['Admin', L('Regole sui dati', 'Rules on data')]], L('Gemini al lavoro.', 'Gemini at work.')),
            dFlash(pFlash(), [[L('Un Gem evita di ripetere il contesto', 'A Gem avoids repeating context'), true], [L('Gemini in Workspace ignora le regole dell’azienda', 'Gemini in Workspace ignores company rules'), false], [L('Un Gem con un compito preciso funziona meglio', 'A Gem with a precise job works better'), true], [L('I Gem si possono usare una volta sola', 'Gems can be used only once'), false]], L('Assistenti su misura.', 'Tailored assistants.')),
        ]),
        lesson('media-live', L('Immagini, video e Gemini Live', 'Images, video and Gemini Live'), [
            P('Nell’app Gemini puoi **creare e modificare immagini** descrivendo ciò che vuoi: cambiare lo sfondo di una foto, unire due immagini, tenere lo stesso personaggio in più scene. I modelli di immagini di Google sono noti anche con il soprannome **Nano Banana**. Con **Veo** si generano brevi video da un testo o da una foto; le quantità disponibili dipendono dal piano.', 'In the Gemini app you can **create and edit images** by describing what you want: change a photo’s background, combine two images, keep the same character across scenes. Google’s image models are also known by the nickname **Nano Banana**. With **Veo** you generate short videos from text or a photo; the amount available depends on your plan.'),
            P('Le immagini e i video creati con l’AI di Google contengono **SynthID**, una filigrana invisibile; puoi anche chiedere a Gemini se un’immagine è stata generata o modificata con gli strumenti di Google. Se SynthID non c’è, però, l’immagine non è per forza autentica: potrebbe venire da un altro strumento.', 'Images and videos made with Google’s AI carry **SynthID**, an invisible watermark; you can also ask Gemini whether an image was generated or edited with Google’s tools. If SynthID is missing, though, the image is not necessarily authentic: it may come from another tool.'),
            Fig(L(fig_gemini_synthid('it'), fig_gemini_synthid('en')),
                L('Un’immagine con una trama di puntini appena visibile, la filigrana, entra in un rombo «SynthID». Se la filigrana è trovata, il riquadro verde dice che è stata creata o modificata con l’AI di Google; se non è trovata, il riquadro grigio tratteggiato dice che l’origine è sconosciuta e che questo non prova che sia vera.', 'An image with a faint dot pattern, the watermark, goes into a “SynthID” diamond. If the watermark is found, the green box says it was made or edited with Google’s AI; if not, the dashed grey box says the origin is unknown and that this does not prove it is real.'),
                L('Il controllo dà una risposta utile solo in un verso: la filigrana assente non dimostra nulla.', 'The check is only conclusive one way: a missing watermark proves nothing.')),
            P('**Gemini Live** è la conversazione a voce in tempo reale: puoi interromperlo, cambiare argomento e **condividere la fotocamera o lo schermo** per chiedere che cosa sta vedendo («che pianta è questa?», «come compilo questo modulo?»). Anche qui valgono le regole sulla privacy: non inquadrare documenti o dati che non vuoi condividere.', '**Gemini Live** is real-time voice conversation: you can interrupt it, change topic and **share your camera or screen** to ask about what it sees (“what plant is this?”, “how do I fill in this form?”). The privacy rules apply here too: do not show documents or data you do not want to share.'),
        ], [
            Q('gm1', L('Che cosa puoi fare con Gemini Live?', 'What can you do with Gemini Live?'), [L('Stampare le conversazioni in PDF', 'Print conversations as PDFs'), L('Parlare a voce e condividere fotocamera o schermo', 'Talk by voice and share your camera or screen'), L('Scaricare modelli aperti sul telefono', 'Download open models to the phone'), L('Leggere le email senza permesso', 'Read emails without permission')], 1, L('Conversazione in tempo reale.', 'Real-time conversation.')),
            Q('gm2', L('Che cos’è SynthID?', 'What is SynthID?'), [L('Un modello per generare video', 'A model for generating video'), L('Un abbonamento di Google', 'A Google subscription'), L('Un formato di file per le foto', 'A file format for photos'), L('Una filigrana invisibile nei contenuti generati da Google', 'An invisible watermark in content generated by Google')], 3, L('Aiuta a riconoscere i contenuti AI di Google.', 'It helps recognise Google AI content.')),
            Q('gm3', L('Un’immagine senza SynthID è sicuramente autentica?', 'Is an image without SynthID surely authentic?'), [L('No, può venire da un altro strumento', 'No, it may come from another tool'), L('Sì, sempre', 'Yes, always'), L('Sì, se è a colori', 'Yes, if it is in colour'), L('Sì, se è in alta risoluzione', 'Yes, if it is high resolution')], 0, L('Ogni strumento ha i suoi segni, o nessuno.', 'Each tool has its own marks, or none.')),
        ], task('text', L('Scrivi una richiesta per **modificare** una foto con Gemini: indica che cosa **togliere** o cambiare e che cosa deve **restare uguale**.', 'Write a request to **edit** a photo with Gemini: state what to **remove** or change and what must **stay the same**.'), '', [re('foto|immagine|photo|image|picture', L('Parli della foto', 'You mention the photo')), re('togli|rimuov|cambia|sostitu|remove|change|replace', L('Che cosa cambiare', 'What to change')), re('uguale|invariat|mantieni|lascia|same|keep|unchanged', L('Che cosa resta uguale', 'What stays the same'))], '', 'Nella foto allegata togli le persone sullo sfondo e sostituisci il cielo grigio con un tramonto, ma lascia uguali il mio viso e i vestiti.'), [
            dMatch(pMatch(), [['Nano Banana', L('Creare e modificare immagini', 'Create and edit images')], ['Veo', L('Brevi video', 'Short videos')], ['SynthID', L('Filigrana invisibile', 'Invisible watermark')], ['Gemini Live', L('Voce, fotocamera e schermo', 'Voice, camera and screen')]], L('Gemini oltre il testo.', 'Gemini beyond text.')),
            dFlash(pFlash(), [[L('Gemini può modificare una foto esistente', 'Gemini can edit an existing photo'), true], [L('In Gemini Live non si può interrompere il modello', 'In Gemini Live you cannot interrupt the model'), false], [L('Le immagini di Google AI contengono una filigrana invisibile', 'Google AI images carry an invisible watermark'), true], [L('Ogni immagine senza filigrana è una foto vera', 'Every image without a watermark is a real photo'), false]], L('Creare e verificare.', 'Create and verify.')),
        ]),
    ],
];
